#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 1024

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ldu(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, v8 v) { memcpy(p, &v, sizeof v); }

/* Computes (or accumulates into) an mr x nr tile of C from packed A and B panels. */
static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    v8 r[MR][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                   {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc) {
                stu(cp, ldu(cp) + r[i][0]);
                stu(cp + 8, ldu(cp + 8) + r[i][1]);
            } else {
                stu(cp, r[i][0]);
                stu(cp + 8, r[i][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int i = 0; i < MR; i++) {
            memcpy(&tmp[i][0], &r[i][0], sizeof(v8));
            memcpy(&tmp[i][8], &r[i][1], sizeof(v8));
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *Ap)
{
    for (int ip = 0; ip < mc; ip += MR) {
        int rows = mc - ip < MR ? mc - ip : MR;
        float *dst = Ap + (size_t)ip * kc;
        for (int r = 0; r < MR; r++) {
            if (r < rows) {
                const float *src = A + (size_t)(i0 + ip + r) * n + p0;
                for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
            } else {
                for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
            }
        }
    }
}

static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc, float *Bp)
{
    for (int jp = 0; jp < nc; jp += NR) {
        int cols = nc - jp < NR ? nc - jp : NR;
        float *dst = Bp + (size_t)jp * kc;
        for (int k = 0; k < kc; k++) {
            const float *src = B + (size_t)(p0 + k) * n + j0 + jp;
            float *d = dst + k * NR;
            if (cols == NR) {
                memcpy(d, src, NR * sizeof(float));
            } else {
                int j = 0;
                for (; j < cols; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, r0, r1;
} job_t;

static void gemm_rows(const float *A, const float *B, float *C, int n, int r0, int r1)
{
    if (r0 >= r1) return;
    float *Ap = aligned_alloc(64, sizeof(float) * MC * KC);
    float *Bp = aligned_alloc(64, sizeof(float) * KC * NC);
    if (!Ap || !Bp) {
        free(Ap); free(Bp);
        for (int i = r0; i < r1; i++)
            for (int j = 0; j < n; j++) {
                float s = 0.0f;
                for (int k = 0; k < n; k++) s += A[(size_t)i * n + k] * B[(size_t)k * n + j];
                C[(size_t)i * n + j] = s;
            }
        return;
    }

    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc != 0;
            pack_b(B, n, pc, kc, jc, nc, Bp);
            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *bp = Bp + (size_t)jr * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(ic + ir) * n + jc + jr, n, mr, nr, acc);
                    }
                }
            }
        }
    }
    free(Ap);
    free(Bp);
}

static void *worker(void *arg)
{
    job_t *j = arg;
    gemm_rows(j->A, j->B, j->C, j->n, j->r0, j->r1);
    return NULL;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    int nt = ncpu > 0 ? (int)ncpu : 1;
    if (nt > 64) nt = 64;
    if (n < 128) nt = 1;
    int max_by_rows = (n + MR * 4 - 1) / (MR * 4);
    if (nt > max_by_rows) nt = max_by_rows;
    if (nt < 1) nt = 1;

    if (nt == 1) {
        gemm_rows(A, B, C, n, 0, n);
        return;
    }

    int chunk = (n + nt - 1) / nt;
    chunk = (chunk + MR - 1) / MR * MR;

    pthread_t th[64];
    job_t jobs[64];
    int created[64];

    for (int t = 0; t < nt; t++) {
        int r0 = t * chunk;
        int r1 = r0 + chunk;
        if (r0 > n) r0 = n;
        if (r1 > n) r1 = n;
        jobs[t] = (job_t){A, B, C, n, r0, r1};
        created[t] = 0;
        if (t > 0 && r0 < r1)
            created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    }

    gemm_rows(A, B, C, n, jobs[0].r0, jobs[0].r1);

    for (int t = 1; t < nt; t++) {
        if (created[t])
            pthread_join(th[t], NULL);
        else
            gemm_rows(A, B, C, n, jobs[t].r0, jobs[t].r1);
    }
}
```
Observation: Compiled and passed the correctness checks.
Runtime: 11.8 ms.
Speedup versus the naive triple loop: 179.78x.
Feedback: **Feedback on Attempt 0 (11.8 ms, 180x)**

The structure is sound: a 6x16 broadcast-FMA micro-kernel, packing, and threads splitting C by rows. The main limits:

1. **Redundant B packing.** Every thread packs the same 256x1024 B panel (1 MB) into its own buffer. That multiplies packing work and memory traffic by the thread count, and gives each core a B footprint far larger than L2. Pack each B block once into a shared buffer, split the packing across threads, and use a barrier. Then divide the `ic`/`jr` loops among threads instead of giving each thread a contiguous row range.

2. **Blocking sizes.** NC=1024 with KC=256 keeps B in L3 at best. Tune so a KC×NR B micro-panel stays in L1 and the MC×KC A block (120×256×4 = 120 KB) fits in L2. Try KC around 384–512 and MC around 72–96, and choose NC per core.

3. **`pack_a` access pattern.** The inner loop writes with stride MR (scattered stores). Loop k on the outside and r on the inside so writes are contiguous.

4. **Kernel details.**
   - Add prefetch of the C tile before the k-loop.
   - Add software prefetch of upcoming A and B data.
   - Unroll k by 4.
   - If AVX-512 is available, widen to a 32-column tile (6x32 or 12x32 with zmm).

5. **Thread overhead.** Threads and buffers are created on every call. Check the core count; hyperthreads rarely help an FMA-bound kernel.

