#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sched.h>

#ifdef __AVX512F__
#define VW 16
#define KC 256
#else
#define VW 8
#define KC 384
#endif
#define MR 6
#define NR (2 * VW)
#define MC 96
#define NC 4096

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof v); }

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* Computes (or accumulates into) an mr x nr tile of C from packed A and B panels. */
static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
    vf c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    vf c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int i = 0; i < MR; i++) {
        __builtin_prefetch(c + (size_t)i * ldc, 1, 3);
        __builtin_prefetch(c + (size_t)i * ldc + NR - 1, 1, 3);
    }

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __builtin_prefetch(b + NR * 8, 0, 3);
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VW);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    vf r[MR][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                   {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc) {
                stu(cp, ldu(cp) + r[i][0]);
                stu(cp + VW, ldu(cp + VW) + r[i][1]);
            } else {
                stu(cp, r[i][0]);
                stu(cp + VW, r[i][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int i = 0; i < MR; i++) {
            memcpy(&tmp[i][0], &r[i][0], sizeof(vf));
            memcpy(&tmp[i][VW], &r[i][1], sizeof(vf));
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *Ap)
{
    for (int ip = 0; ip < mc; ip += MR) {
        int rows = mc - ip < MR ? mc - ip : MR;
        float *dst = Ap + (size_t)ip * kc;
        const float *src = A + (size_t)(i0 + ip) * n + p0;
        if (rows == MR) {
            const float *s0 = src, *s1 = src + n, *s2 = src + 2 * (size_t)n;
            const float *s3 = src + 3 * (size_t)n, *s4 = src + 4 * (size_t)n, *s5 = src + 5 * (size_t)n;
            for (int k = 0; k < kc; k++) {
                float *d = dst + k * MR;
                d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
            }
        } else {
            for (int k = 0; k < kc; k++) {
                float *d = dst + k * MR;
                int r = 0;
                for (; r < rows; r++) d[r] = src[(size_t)r * n + k];
                for (; r < MR; r++) d[r] = 0.0f;
            }
        }
    }
}

/* Packs NR-wide panels [p_begin, p_end) of the kc x nc block of B. */
static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc,
                   int p_begin, int p_end, float *Bp)
{
    for (int p = p_begin; p < p_end; p++) {
        int jp = p * NR;
        int cols = nc - jp < NR ? nc - jp : NR;
        float *dst = Bp + (size_t)jp * kc;
        const float *src = B + (size_t)p0 * n + j0 + jp;
        if (cols == NR) {
            for (int k = 0; k < kc; k++)
                memcpy(dst + k * NR, src + (size_t)k * n, NR * sizeof(float));
        } else {
            for (int k = 0; k < kc; k++) {
                float *d = dst + k * NR;
                const float *s = src + (size_t)k * n;
                int j = 0;
                for (; j < cols; j++) d[j] = s[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }
    }
}

typedef struct {
    volatile int count;
    volatile int gen;
    int nt;
} barrier_t;

static void barrier_wait(barrier_t *b)
{
    int g = __atomic_load_n(&b->gen, __ATOMIC_ACQUIRE);
    if (__atomic_add_fetch(&b->count, 1, __ATOMIC_ACQ_REL) == b->nt) {
        __atomic_store_n(&b->count, 0, __ATOMIC_RELAXED);
        __atomic_store_n(&b->gen, g + 1, __ATOMIC_RELEASE);
    } else {
        long spins = 0;
        while (__atomic_load_n(&b->gen, __ATOMIC_ACQUIRE) == g) {
            cpu_relax();
            if (++spins > 4096) { sched_yield(); spins = 0; }
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    float *Bp[2];
    barrier_t *bar;
    int n, nt, tid, r0, r1;
} job_t;

static void gemm_thread(job_t *j)
{
    const float *A = j->A, *B = j->B;
    float *C = j->C;
    int n = j->n, nt = j->nt, tid = j->tid, r0 = j->r0, r1 = j->r1;
    float Ap[MC * KC] __attribute__((aligned(64)));

    int it = 0;
    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        int np = (nc + NR - 1) / NR;
        for (int pc = 0; pc < n; pc += KC, it++) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc != 0;
            float *Bp = j->Bp[it & 1];

            int pb = (int)((long)np * tid / nt);
            int pe = (int)((long)np * (tid + 1) / nt);
            pack_b(B, n, pc, kc, jc, nc, pb, pe, Bp);
            if (nt > 1) barrier_wait(j->bar);

            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *bp = Bp + (size_t)jr * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(ic + ir) * n + jc + jr, n, mr, nr, acc);
                    }
                }
            }
        }
    }
}

static void *worker(void *arg)
{
    gemm_thread(arg);
    return NULL;
}

static void naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *c = C + (size_t)i * n;
        for (int jj = 0; jj < n; jj++) c[jj] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *b = B + (size_t)k * n;
            for (int jj = 0; jj < n; jj++) c[jj] += a * b[jj];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    int nt = ncpu > 0 ? (int)ncpu : 1;
    if (nt > 64) nt = 64;
    if (n < 128) nt = 1;
    int max_by_rows = (n + MR * 4 - 1) / (MR * 4);
    if (nt > max_by_rows) nt = max_by_rows;
    if (nt < 1) nt = 1;

    int ncmax = n < NC ? n : NC;
    size_t bsz = (size_t)KC * (((ncmax + NR - 1) / NR) * NR);
    float *Bbuf = aligned_alloc(64, ((sizeof(float) * 2 * bsz + 63) / 64) * 64);
    if (!Bbuf) { naive(A, B, C, n); return; }

    /* Split rows into MR-aligned chunks. */
    int chunk = (n + nt - 1) / nt;
    chunk = (chunk + MR - 1) / MR * MR;
    while (nt > 1 && (long)chunk * (nt - 1) >= n) nt--;

    barrier_t bar = {0, 0, nt};
    pthread_t th[64];
    job_t jobs[64];

    for (int t = 0; t < nt; t++) {
        int r0 = t * chunk, r1 = r0 + chunk;
        if (r0 > n) r0 = n;
        if (r1 > n) r1 = n;
        jobs[t] = (job_t){A, B, C, {Bbuf, Bbuf + bsz}, &bar, n, nt, t, r0, r1};
    }

    int ok = 1;
    int created = 1;
    for (int t = 1; t < nt; t++) {
        if (pthread_create(&th[t], NULL, worker, &jobs[t]) != 0) { ok = 0; break; }
        created++;
    }

    if (!ok) {
        /* Cannot run the barrier protocol with fewer threads than planned:
           release the ones that started by finishing as single thread is unsafe,
           so fall back to running the missing workers here sequentially is also
           impossible. Instead, let created threads run with a re-sized barrier. */
        bar.nt = created; /* not reached in practice; recompute below */
    }

    if (ok) {
        gemm_thread(&jobs[0]);
        for (int t = 1; t < nt; t++) pthread_join(th[t], NULL);
    } else {
        /* Threads already started expect nt participants; join them is impossible
           without the rest, so spawn remaining participants by retrying. */
        for (int t = created; t < nt; t++)
            while (pthread_create(&th[t], NULL, worker, &jobs[t]) != 0) sched_yield();
        bar.nt = nt;
        gemm_thread(&jobs[0]);
        for (int t = 1; t < nt; t++) pthread_join(th[t], NULL);
    }

    free(Bbuf);
}
```
Observation: Compiled and passed the correctness checks.
Runtime: 15.8 ms.
Speedup versus the naive triple loop: 134.18x.
Feedback: **Feedback on Attempt 1 (15.8 ms, slower than Attempt 0's 11.8 ms)**

1. **Work split is unchanged.** Threads still own contiguous row ranges, so each one streams the entire shared B block through its own L1/L2 for every MC block. Sharing the buffer saved only the packing. Split the `jr` loop (or `ic`×`jr` tiles) among threads so each core touches only part of B. For example, every thread packs its own A block, then works on a disjoint range of NR panels.

2. **KC=384 overflows L1 on AVX2.** A B micro-panel is 384×16×4 = 24 KB, plus 9 KB of A, which exceeds 32 KB of L1 when C traffic is included. Go back to KC=256, which also divides typical n evenly and avoids a short final `kc`. Size MC×KC to about half of L2.

3. **Barrier cost.** There is a spin barrier on every `pc` step, and `sched_yield` runs with nt equal to all logical CPUs. Hyperthread siblings spinning steal FMA issue slots. Use physical cores only. The second B buffer gives no benefit while every iteration still has a full barrier.

4. **Prefetch every k iteration** adds uops to an issue-bound loop. Prefetch once per cache line (every 1–2 k), aimed about 4–8 iterations ahead, and also prefetch A.

5. Threads are still created on every call. Use a persistent pool.

