static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* Full MR x NR tile: C (=|+=) Apanel * Bpanel. No edge handling in here. */
static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int acc)
{
#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

#define PFC(i) __builtin_prefetch(c + (size_t)(i) * ldc, 1, 3); \
               __builtin_prefetch(c + (size_t)(i) * ldc + NR - 1, 1, 3);
    ROWS(PFC)
#undef PFC

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)b;
        vf b1 = *(const vf *)(b + VW);
#define STEP(i) { float t = a[i]; c##i##_0 += t * b0; c##i##_1 += t * b1; }
        ROWS(STEP)
#undef STEP
        a += MR;
        b += NR;
    }

    if (acc) {
#define ACC(i) { float *p = c + (size_t)(i) * ldc; \
                 stu(p, ldu(p) + c##i##_0); stu(p + VW, ldu(p + VW) + c##i##_1); }
        ROWS(ACC)
#undef ACC
    } else {
#define ST(i) { float *p = c + (size_t)(i) * ldc; stu(p, c##i##_0); stu(p + VW, c##i##_1); }
        ROWS(ST)
#undef ST
