            const float *b = B + (size_t)k * n;
            for (int jj = 0; jj < n; jj++) c[jj] += a * b[jj];
        }
    }
}

static void gemm_rows(const float *A, const float *B, float *C, int n, int r0, int r1, int tid)
{
    if (r0 >= r1) return;
    /* Stagger buffers per thread so siblings' panels do not share cache sets. */
    size_t off = (size_t)(tid % 16) * (64 + 1024) / sizeof(float);
    float *Abuf = aligned_alloc(64, sizeof(float) * (MC * KC + 16 * 1088 / 4 + 64));
    float *Bbuf = aligned_alloc(64, sizeof(float) * (KC * NC + 16 * 1088 / 4 + 64));
    if (!Abuf || !Bbuf) {
        free(Abuf); free(Bbuf);
        naive_rows(A, B, C, n, r0, r1);
        return;
    }
    float *Ap = Abuf + off, *Bp = Bbuf + off;

    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        int nfull = nc / NR * NR;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc != 0;
            pack_b(B, n, pc, kc, jc, nc, Bp);
            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                int mfull = mc / MR * MR;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                float *cb = C + (size_t)ic * n + jc;
                for (int jr = 0; jr < nfull; jr += NR) {
                    const float *bp = Bp + (size_t)jr * kc;
                    int ir = 0;
                    for (; ir < mfull; ir += MR)
                        kernel(kc, Ap + (size_t)ir * kc, bp, cb + (size_t)ir * n + jr, n, acc);
                    if (ir < mc)
                        kernel_edge(kc, Ap + (size_t)ir * kc, bp, cb + (size_t)ir * n + jr,
                                    n, mc - ir, NR, acc);
                }
                if (nfull < nc) {
                    const float *bp = Bp + (size_t)nfull * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel_edge(kc, Ap + (size_t)ir * kc, bp, cb + (size_t)ir * n + nfull,
                                    n, mr, nc - nfull, acc);
                    }
                }
            }
        }
    }
    free(Abuf);
    free(Bbuf);
}

static void *worker(void *arg)
{
    job_t *j = arg;
    gemm_rows(j->A, j->B, j->C, j->n, j->r0, j->r1, j->tid);
    return NULL;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    int nt = ncpu > 0 ? (int)ncpu : 1;
    if (nt > 64) nt = 64;
    if (n < 128) nt = 1;
    int max_by_rows = (n + 24 - 1) / 24;
    if (nt > max_by_rows) nt = max_by_rows;
    if (nt < 1) nt = 1;

    if (nt == 1) {
        gemm_rows(A, B, C, n, 0, n, 0);
        return;
    }

    int chunk = (n + nt - 1) / nt;
    chunk = (chunk + MR - 1) / MR * MR;

    pthread_t th[64];
    job_t jobs[64];
    int created[64];

    for (int t = 0; t < nt; t++) {
        int r0 = t * chunk;
        int r1 = r0 + chunk;
        if (r0 > n) r0 = n;
        if (r1 > n) r1 = n;
        jobs[t] = (job_t){A, B, C, n, r0, r1, t};
        created[t] = 0;
        if (t > 0 && r0 < r1)
            created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    }

    gemm_rows(A, B, C, n, jobs[0].r0, jobs[0].r1, 0);

    for (int t = 1; t < nt; t++) {
        if (created[t])
            pthread_join(th[t], NULL);
        else
            gemm_rows(A, B, C, n, jobs[t].r0, jobs[t].r1, t);
    }
