    FILE *f = fopen(path, "r");
    if (!f) return -1;
    int rep = -1;
    if (fscanf(f, "%d", &rep) != 1) rep = -1;
    fclose(f);
    return rep;
}
#endif

/* Counts physical cores in the affinity mask; falls back to logical CPUs. */
static int detect_threads(void)
{
    int n = 0;
#ifdef __linux__
    cpu_set_t cs;
    if (sched_getaffinity(0, sizeof cs, &cs) == 0) {
        n = CPU_COUNT(&cs);
        static unsigned char seen[CPU_SETSIZE];
        int cores = 0, ok = 1;
        for (int c = 0; c < CPU_SETSIZE; c++) {
            if (!CPU_ISSET(c, &cs)) continue;
            int r = core_rep(c);
            if (r < 0 || r >= CPU_SETSIZE) { ok = 0; break; }
            if (!seen[r]) { seen[r] = 1; cores++; }
        }
        if (ok && cores > 0) n = cores;
    }
#endif
    if (n <= 0) {
        long c = sysconf(_SC_NPROCESSORS_ONLN);
        n = c > 0 ? (int)c : 1;
    }
    if (n > 64) n = 64;
    return n;
}

static int g_threads;

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    if (g_threads <= 0) g_threads = detect_threads();
    int nt = g_threads;
    if (n < 128) nt = 1;
    int max_by_rows = (n + MR * 4 - 1) / (MR * 4);
    if (nt > max_by_rows) nt = max_by_rows;
    if (nt < 1) nt = 1;

    if (nt == 1) {
        gemm_rows(A, B, C, n, 0, n);
        return;
    }

    int chunk = (n + nt - 1) / nt;
    chunk = (chunk + MR - 1) / MR * MR;

    pthread_t th[64];
    job_t jobs[64];
    int created[64];

    for (int t = 0; t < nt; t++) {
        int r0 = t * chunk;
        int r1 = r0 + chunk;
        if (r0 > n) r0 = n;
        if (r1 > n) r1 = n;
        jobs[t] = (job_t){A, B, C, n, r0, r1};
        created[t] = 0;
        if (t > 0 && r0 < r1)
            created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    }

    gemm_rows(A, B, C, n, jobs[0].r0, jobs[0].r1);

    for (int t = 1; t < nt; t++) {
        if (created[t])
            pthread_join(th[t], NULL);
        else
            gemm_rows(A, B, C, n, jobs[t].r0, jobs[t].r1);
    }
}
